import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long x = nextLong();
        int[] factor = new int[n];
        for (int i = 0; i < n; i++) factor[i] = nextInt();
        // Only the factor[i] largest values of each row can be worth taking.
        int[] candidates = new int[n * n];
        int count = 0;
        int[] row = new int[n];
        for (int r = 0; r < n; r++) {
            for (int j = 0; j < n; j++) row[j] = nextInt();
            Arrays.sort(row);
            for (int j = n - 1; j >= n - Math.min(factor[r], n); j--) candidates[count++] = row[j];
        }
        if (count < x) {
            System.out.println(-1);
            return;
        }
        Arrays.sort(candidates, 0, count);
        long sum = 0;
        for (int j = count - 1; j >= count - x; j--) sum += candidates[j];
        System.out.println(sum);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	x := int(nextInt())
	factor := make([]int, n)
	for i := range factor {
		factor[i] = int(nextInt())
	}
	// Only the factor[i] largest values of each row can be worth taking.
	candidates := make([]int64, 0, n*n)
	row := make([]int64, n)
	for r := 0; r < n; r++ {
		for j := range row {
			row[j] = nextInt()
		}
		slices.Sort(row)
		for j := n - 1; j >= n-min(factor[r], n); j-- {
			candidates = append(candidates, row[j])
		}
	}
	if len(candidates) < x {
		fmt.Println(-1)
		return
	}
	slices.Sort(candidates)
	var sum int64
	for _, v := range candidates[len(candidates)-x:] {
		sum += v
	}
	fmt.Println(sum)
}
